const DuckDBDriver = require('@cubejs-backend/duckdb-driver');

const GCS_ACCESS_KEY = process.env.ACCESS_KEY;
const GCS_SECRET_KEY = process.env.SECRET_KEY;
const BUCKET = 'scbi-ducklake-myanalyticsproduct';

async function introspect() {
  const driver = new DuckDBDriver({});
  await driver.query("INSTALL httpfs; LOAD httpfs; SET s3_endpoint = 'storage.googleapis.com'; SET s3_url_style = 'path'; SET s3_access_key_id = '" + GCS_ACCESS_KEY + "'; SET s3_secret_access_key = '" + GCS_SECRET_KEY + "';", []);

  const tables = [
    'scbi_cdp_mart/cnf__dim_fund',
    'scbi_cdp_mart/cnf__dim_client',
    'scbi_cdp_mart/cnf__dim_employer',
    'scbi_cdp_mart/cnf__dim_member',
    'scbi_cdp_mart/cnf__fact_member_investment_aua',
    'scbi_cdp_mart/cnf__fact_annuity_quotations'
  ];

  for (const t of tables) {
    try {
      const res = await driver.query("DESCRIBE SELECT * FROM read_parquet('s3://" + BUCKET + "/" + t + "/*.parquet') LIMIT 1", []);
      console.log('TABLE: ' + t);
      console.log(res.map(r => r.column_name + ' (' + r.column_type + ')').join(', '));
      console.log('---');
    } catch(e) {
      console.log('TABLE ERROR ' + t + ':', e.message);
    }
  }
  process.exit(0);
}

introspect();
